"""The privacy scrubber.

Pull requests must not mention the tooling that produced them. These tests are
the guard rail for that promise.
"""

from __future__ import annotations

import pytest

from deps_bot import sanitize


@pytest.mark.parametrize(
    "text",
    [
        "Updated by deps-bot",
        "The agent regenerated the lockfile",
        "The model updated this line",
        "Generated by AI",
        "Co-authored-by: qwen3-8-27b",
        "This was written by the LLM",
        "Ran inside bubblewrap",
        "claude wrote this",
        "gpt-4 suggested the change",
    ],
)
def test_leak_markers_are_detected(text):
    assert sanitize.contains_leak(text)


@pytest.mark.parametrize(
    "text",
    [
        "vitest 5 no longer allows vi.fn() mocks to be used with new.",
        "The lockfile was regenerated with --legacy-peer-deps.",
        "Updated the Octokit mock to use a regular function.",
    ],
)
def test_ordinary_prose_is_left_alone(text):
    assert not sanitize.contains_leak(text)


def test_scrub_removes_tool_references():
    out = sanitize.scrub_text("The agent regenerated the lockfile using deps-bot.")
    assert "deps-bot" not in out
    assert "agent" not in out.lower()


def test_scrub_keeps_technical_punctuation():
    """vi.fn() must survive scrubbing - removing the parens changes the code."""
    out = sanitize.scrub_text("the model broke vi.fn() mocks")
    assert "vi.fn()" in out


def test_scrub_leaves_clean_text_alone():
    text = "vitest 5 removed `new` support for arrow-function mocks."
    assert sanitize.scrub_text(text) == text


def test_scan_diff_finds_markers_in_added_lines():
    diff = (
        "diff --git a/src/a.ts b/src/a.ts\n"
        "--- a/src/a.ts\n"
        "+++ b/src/a.ts\n"
        "@@\n"
        "+// Updated by deps-bot\n"
        "+export const x = 1;\n"
    )
    hits = sanitize.scan_diff(diff)
    assert len(hits) == 1
    assert hits[0]["file"] == "src/a.ts"
    assert hits[0]["is_comment"] is True


def test_scan_diff_ignores_removed_lines():
    diff = (
        "diff --git a/src/a.ts b/src/a.ts\n"
        "--- a/src/a.ts\n"
        "+++ b/src/a.ts\n"
        "@@\n"
        "-// Updated by deps-bot\n"
    )
    assert sanitize.scan_diff(diff) == []


def test_scan_diff_flags_code_as_blocking():
    diff = (
        'diff --git a/src/a.ts b/src/a.ts\n+++ b/src/a.ts\n@@\n+const banner = "generated by ai";\n'
    )
    hits = sanitize.scan_diff(diff)
    assert hits and hits[0]["is_comment"] is False


def test_strip_comment_hits_removes_only_comments():
    files = {
        "src/a.ts": [
            "// Updated by deps-bot",
            "export const x = 1;",
            'const banner = "generated by ai";',
        ]
    }
    hits = sanitize.scan_diff(
        "diff --git a/src/a.ts b/src/a.ts\n+++ b/src/a.ts\n"
        "+// Updated by deps-bot\n"
        '+const banner = "generated by ai";\n'
    )
    removed = sanitize.strip_comment_hits(hits, files)
    assert len(removed) == 1
    assert files["src/a.ts"] == [
        "export const x = 1;",
        'const banner = "generated by ai";',
    ]


def test_scrubbing_can_leave_a_marker_behind():
    """A phrase that survives scrubbing must still be detectable."""
    text = "written by qwen3-8-27b"
    scrubbed = sanitize.scrub_text(text)
    assert sanitize.contains_leak(scrubbed) or scrubbed != text


def test_note_dropping_when_a_marker_survives():
    """The pipeline drops a note that still mentions the tooling."""
    from deps_bot.pipeline import Worker

    worker = Worker.__new__(Worker)
    # "the model" is replaced by "the change", but a bare model name is not.
    note = "regenerated with qwen3-8-27b"
    assert sanitize.contains_leak(note)
    assert worker._public_note(f"NOTES: {note}") == ""
